    "caseText": "【2026年4月1日基準の独自演習】石田さんの父は、祖父が相続開始直前まで1人で居住していた自宅を2024年4月1日に相続した。父の自宅とは別の場所にあり、相続取得者は父1人である。土地360㎡は第一種住居地域、指定建蔽率60％、指定容積率300％、前面道路は1本で幅員6m、道路による容積率係数は4/10とする。道路後退・角地・防火等の緩和・特定道路による割増し・他の容積率特例はなく、容積率不算入となる床面積もない。旧家屋は1976年建築の戸建てで、区分所有建物ではない。【売却案】相続後に事業・貸付け・居住に使用せず、2026年中の売却を検討する。売却対価は8,000万円、他の分割売却等はなく、特別な関係のない第三者への売却を想定する。被相続人の居住用家屋等の譲渡所得の特別控除について、建築時期・譲渡対価・最高控除額を問う。耐震改修または取壊し、確定申告・確認書、他の特例との調整等の要件は個別に確認するため、適用確定や実際の控除額を判定する設例ではない。【別の貸付け案】売却案とは択一の案として、土地を小売企業へ専ら店舗用建物のために事業用定期借地権を設定して貸すことも検討する。住居との併用は想定しない。貸付け案を実行した後も売却案の空き家特例がそのまま適用されるとは扱わない。容積率の上限計算だけで実際に建築できる規模や許可の可否を確定しない。",
    "question": "設例の条件で、容積率算定に用いる延べ面積の上限はどれか。",
