    "caseTitle": "企業のリスク管理と退職所得",
    "caseText": "食品製造会社の創業者である高橋さんは、2026年4月1日現在の制度を用いて退任時の資金計画と企業のリスク管理を検討している。今回の退職金の計算対象となる勤務期間は全て役員としての期間で、2001年10月1日から2026年4月30日までの24年7か月とする。同日の退任に伴って会社から支払われる退職手当は、源泉徴収前の収入金額で2,300万円である。従業員としての勤務期間はなく、勤続期間の調整が必要となる過去・同年の退職手当や確定拠出年金等の一時金もない。障害者になったことが直接の原因で退職するものではない。2026年分の退職所得の金額を求め、所得税額・住民税額や会社側の損金算入額は計算しない。会社は、製品事故・施設事故・従業員の業務上災害への備えも検討している。今回比較する契約では、PL賠償は引渡し後の食品の欠陥に起因する第三者の身体障害・財物損壊に対する会社の法律上の損害賠償責任を対象とする。施設賠償は、施設の管理上の不備に起因する第三者の身体障害・財物損壊に対する会社の法律上の損害賠償責任を対象とする。使用者賠償は、従業員の業務上災害について会社が法律上の損害賠償責任を負い、政府労災保険や法定外補償規程等の給付を超える賠償損害を対象とする。法定外補償規程に基づく上乗せ給付のみを、使用者賠償の支払対象と判定しない。本問では上記の対象区分への当てはめを行い、実際の保険金支払いは個別契約の免責・支払限度・事故条件等を確認して判断する。",
    "question": "設例の2026年分の退職所得控除額はいくらか。",
