    "caseTitle": "贈与と相続による資産承継",
    "caseText": "伊藤さんは2026年4月1日現在の制度で、贈与と相続による資産承継を検討している。【贈与の設例】2026年中、同年1月1日現在40歳の実子へ現金550万円を贈与する。父から実子への贈与であり、子は他の贈与を受けておらず、暦年課税を適用する。相続時精算課税を選択しておらず、非課税特例はない。特例贈与財産の速算表の抜粋：基礎控除後の課税価格400万円超600万円以下は20％・控除30万円、600万円超1,000万円以下は30％・控除90万円。【別の相続設例】上記の贈与の実行とは独立して、2026年4月1日に本人の相続が開始したと仮定する。法定相続人は法律上の配偶者と実子2人で、放棄・養子・代襲はない。本人が全額保険料を負担した本人死亡の生命保険金3,000万円を配偶者だけが一時金で受け取り、他の死亡保険金はない。相続開始直前に本人が居住していた自宅の敷地全体は240㎡で、特例適用前の相続税評価額は4,800万円である。遺産分割により配偶者が敷地全体を取得し、特定居住用宅地等の特例を適用する。他に選択する宅地はなく、必要書類を添付した申告等の手続要件は満たすものとする。敷地の1㎡当たりの評価額は全体で均一とし、建物価額や配偶者居住権は今回の計算対象外とする。今回求めるのは贈与税額・死亡保険金の非課税限度額・遺産の基礎控除・敷地の算入価額・法定相続分であり、遺産全体の相続税額や生前贈与の加算は計算しない。",
