    "caseText": "【2026年4月1日基準の独自演習】石田さんの父について、2026年分の所得税を2026年末の年末調整または翌年の確定申告で計算する。父の給与収入は源泉徴収前の780万円で、この収入区分の給与所得控除は収入×10％＋110万円。所得金額調整控除・特定支出控除はない。本人が全額保険料を負担した15年満期・平準払の養老保険から、本人が満期一時金740万円を受け取り、正味払込保険料は620万円とする。金融類似商品の源泉分離課税の対象ではなく、他の一時所得・追加費用・他の所得はない。父が自己および生計を一にする家族の控除対象医療費48万円を実際に支払い、その同じ医療費だけを補てんする給付金は10万円で、補てん超過はない。長男は2026年12月31日現在20歳の国内居住者で、父と生計を一にし、給与収入80万円だけを得る。他に長男を扶養親族として控除する人はいない。長男は青色事業専従者給与の受給者でも白色事業専従者でもなく、障害者ではない。長男の給与所得控除は2026年分に適用される74万円、扶養親族の合計所得要件は62万円以下を用いる。これらの改正は2026年12月1日施行で2026年分から適用される条件とし、施行前の準確定申告等を対象としない。父の総所得金額と医療費控除・長男の扶養控除を区別し、所得税額や住民税額は求めない。",
    "question": "通常の医療費控除額はどれか。",
