    "caseText": "【2026年4月1日基準の独自演習】安藤さんの家族は株式投資を検討している。上場会社の株価3000円、発行済株式数100万株、当期純利益250,000,000円、自己資本2,000,000,000円。自己株式・潜在株式・株式分割はない。注文方法と価格・時間優先の基本原則も確認したい。指値の買い注文について、通常のザラバ取引を想定し、寄り付き・引け・特別な配分等は考慮しない。財務数値は同じ決算期・普通株式を対象とし、EPS/BPSは設例の株数で計算する。単位は利益・自己資本の総額が円、株価や1株当たりの指標が円/株、PER/PBRが倍である。実際の投資判断、将来利益、税・手数料は計算しない。",
