    "answer": 2,
    "explanation": "①○：地震保険だけを単独で契約することはできず、火災保険に付帯します。②○：建物と家財は別に契約し、各火災保険金額の30～50％の範囲内、かつ建物5,000万円・家財1,000万円までです。③×：対象は居住用建物と生活用家財で、自動車や販売用商品は対象外です。",
