    "caseTitle": "住宅の火災・地震リスク",
    "caseText": "佐藤さんは自宅として使用する居住用住宅を購入し、2026年4月1日現在の制度で保険を検討している。火災保険の保険金額は建物4,600万円、生活用家財800万円とする。建物と家財のそれぞれに地震保険を付帯し、どちらも対応する火災保険金額の40％を地震保険金額とする。自動車や販売用商品は生活用家財に含めない。2026年分の所得税の計算では、その年中に本人が支払う控除対象の地震保険料を32,000円とする。地震保険料とは別の保険契約に基づく旧長期損害保険料18,000円も本人が支払う。この旧契約は2006年1月1日に締結・開始し、満期返戻金があり、保険期間は同日から2035年12月31日までの30年間である。2007年1月1日以後に契約変更はなく、控除対象の要件を満たすものとする。保険料は年額の与件であり、所在地・構造別の料率計算は行わない。保険金額の設定と、実際の損害認定による支払保険金は区別し、本設例では支払保険金を計算しない。他の控除対象保険料はなく、住民税の控除額は計算しない。",
    "question": "2026年分の所得税における、設例の地震保険料控除額はいくらか。",
    "kind": "choice",
    "answer": 1,
    "explanation": "地震保険料の控除額は32,000円です。別契約の旧長期損害保険料18,000円は10,000円超20,000円以下なので18,000×1/2＋5,000＝14,000円。合計32,000＋14,000＝46,000円で、両区分合算の上限50,000円以内です。同一契約に両方の保険料がある場合は一方を選択しますが、本設例は別契約なので合算します。住民税の控除額ではありません。",
