    "question": "設例で明示した補償区分に照らした、次の説明の適否の組合せはどれか。①引渡し後の食品の欠陥による購入者の食中毒は、施設賠償の区分に当てはめる。②店舗の床の管理上の不備による来店客の転倒は、施設賠償の区分に当てはめる。③従業員の業務上災害について会社が法律上の損害賠償責任を負い、政府労災・法定外補償等の給付を超える賠償損害が生じた場合は、使用者賠償の区分に当てはめる。",
